from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class EthifParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        self.set_linkSelectorDN()
        if not self.is_mo_ecpri and self.mo_num == '1':
            self.set_parameter('sbsTotal', self.enb_ent_config.get('sbs_total', 4000))
            self.set_parameter('shapingOverhead', "IP packet")
            self.set_parameter('sirTotal', 1000000)
            self.set_parameter('txPriorityTagging', "false")

    def set_linkSelectorDN(self):
        if self.is_mo_ecpri:
            self.set_parameter('linkSelectorDN', "MRBTS-{}/TNLSVC-1/TNL-2/ETHSVC-1/ETHLK-{}".format(
                self.enb_ent_config['id'], self.mo_num
            ))
        elif self.mo_num == '1':
            self.set_parameter('linkSelectorDN', "MRBTS-{}/TNLSVC-1/TNL-1/ETHSVC-1/L2SWI-1/IBRGPRT-1".format(
                self.enb_ent_config['id']
            ))
        elif self.mo_num == '2':
            self.set_parameter('linkSelectorDN', "MRBTS-{}/TNLSVC-1/TNL-1/ETHSVC-1/L2SWI-1/BRGPRT-1".format(
                self.enb_ent_config['id']
            ))
